do $$ declare actor uuid:='10000000-0000-4000-8000-000000000021'; rid uuid; body jsonb; data jsonb; task jsonb; begin
 select recording_id into rid from public.recording_transcriptions limit 1;
 if not exists(select 1 from public.recording_transcriptions where recording_id=rid and language_hint='ja' and status='ready' and text='Synthetic original memory' and published and version=7 and attempts=3) then raise exception 'migration changed historical state';end if;
 body:=jsonb_build_object('action','retryTranscription','recordingId',rid,'memberId','wang-heisei','version',7,'languageHint','zh');
 begin perform public.staff_action('10000000-0000-4000-8000-000000000022',body);raise exception 'outsider accepted';exception when others then if sqlerrm<>'STAFF_REQUIRED' then raise;end if;end;
 begin perform public.staff_action(actor,body||'{"memberId":"forged"}');raise exception 'forged member accepted';exception when others then if sqlerrm<>'MEMBER_REQUIRED' then raise;end if;end;
 begin perform public.staff_action(actor,body||'{"languageHint":"zh-CN"}');raise exception 'invalid language accepted';exception when others then if sqlerrm<>'REQUEST_INVALID' then raise;end if;end;
 begin perform public.staff_action(actor,body||'{"version":7.1}');raise exception 'fraction accepted';exception when others then if sqlerrm<>'VERSION_CONFLICT' then raise;end if;end;
 update public.recordings set transcription_consent=false where id=rid;
 begin perform public.staff_action(actor,body);raise exception 'no consent accepted';exception when others then if sqlerrm<>'TRANSCRIPTION_CONSENT_REQUIRED' then raise;end if;end;
 update public.recordings set transcription_consent=true where id=rid;
 perform public.staff_action(actor,body);
 if not exists(select 1 from public.recording_transcriptions where recording_id=rid and language_hint='zh' and status='pending' and text='Synthetic original memory' and not published and version=8 and attempts=0 and lease_token is null and error_code is null) then raise exception 'retry did not retain/reset/withdraw';end if;
 data:=public.staff_action(actor,'{"action":"list"}');
 if data->'cards'->0->'recording'->'transcription'->>'languageHint'<>'zh' then raise exception 'list missing language';end if;
 if data->'cards'->0->'recording'->'latestReview'->>'action'<>'staff_retry_transcription' then raise exception 'retry attribution missing';end if;
 if not exists(select 1 from public.audit_log where action='staff_retry_transcription' and details->>'memberName'='王 平成' and details->>'languageHint'='zh' and details->>'previousPublished'='true' and details::text not like '%Synthetic%') then raise exception 'retry audit incorrect';end if;
 begin perform public.staff_action(actor,body);raise exception 'stale accepted';exception when others then if sqlerrm<>'VERSION_CONFLICT' then raise;end if;end;
 body:=body||'{"version":8}';
 begin perform public.staff_action(actor,body);raise exception 'pending accepted';exception when others then if sqlerrm<>'TRANSCRIPTION_IN_PROGRESS' then raise;end if;end;
 begin perform public.staff_action(actor,jsonb_build_object('action','save','recordingId',rid,'memberId','wang-heisei','version',8,'text','Synthetic original memory','published',true));raise exception 'retained text published';exception when others then if sqlerrm<>'TRANSCRIPTION_IN_PROGRESS' then raise;end if;end;
 begin perform public.admin_action(actor,jsonb_build_object('action','saveTranscription','recordingId',rid,'version',8,'text','Synthetic original memory','published',true));raise exception 'staff accessed admin guard';exception when others then if sqlerrm<>'OPERATOR_REQUIRED' then raise;end if;end;
 update public.operator_profiles set role='admin' where user_id=actor;
 begin perform public.admin_action(actor,jsonb_build_object('action','saveTranscription','recordingId',rid,'version',8,'text','Synthetic original memory','published',true));raise exception 'admin republished retained text';exception when others then if sqlerrm<>'TRANSCRIPTION_IN_PROGRESS' then raise;end if;end;
 if not exists(select 1 from public.recording_transcriptions where recording_id=rid and status='pending' and version=8 and not published and text='Synthetic original memory') then raise exception 'admin guard modified queued task';end if;
 update public.operator_profiles set role='staff' where user_id=actor;
 task:=public.claim_transcription();
 if task->>'languageHint'<>'zh' then raise exception 'worker missing language';end if;
 begin perform public.staff_action(actor,body);raise exception 'processing accepted';exception when others then if sqlerrm<>'TRANSCRIPTION_IN_PROGRESS' then raise;end if;end;
 update public.operator_profiles set role='admin' where user_id=actor;
 begin perform public.admin_action(actor,jsonb_build_object('action','saveTranscription','recordingId',rid,'version',8,'text','Synthetic original memory','published',false));raise exception 'admin canceled processing retry';exception when others then if sqlerrm<>'TRANSCRIPTION_IN_PROGRESS' then raise;end if;end;
 update public.operator_profiles set role='staff' where user_id=actor;
 perform public.finish_transcription(rid,(task->>'leaseToken')::uuid,8,'Synthetic Chinese result',null,0);
 begin perform public.staff_action(actor,body||'{"version":9}');raise exception 'rate limit ignored';exception when others then if sqlerrm<>'TRANSCRIPTION_RATE_LIMITED' then raise;end if;end;
 update public.recording_transcriptions set manual_retry_at=now()-interval '2 minutes' where recording_id=rid;
 perform public.staff_action(actor,body||'{"version":9,"languageHint":"auto"}');
 if public.finish_transcription(rid,(task->>'leaseToken')::uuid,8,'Late old result',null,0) then raise exception 'late old result accepted';end if;
 if not exists(select 1 from public.recording_transcriptions where recording_id=rid and text='Synthetic Chinese result' and status='pending' and language_hint='auto' and version=10) then raise exception 'new generation overwritten';end if;
 update public.tags set status='disabled' where id='20000000-0000-4000-8000-000000000021';
 begin perform public.staff_action(actor,body||'{"version":10}');raise exception 'disabled accepted';exception when others then if sqlerrm<>'RECORDING_NOT_FOUND' then raise;end if;end;
 if has_function_privilege('authenticated','public.claim_recording_transcription(uuid,text,text,integer,bigint,text,jsonb,text,boolean,text)','EXECUTE') then raise exception 'public language claim access';end if;
end $$;
